select ss.product_id, date_trunc('MONTH', ss.sale_date) as sale_month, max(i.quantity) - min(i.quantity) as quantity_range, max(i.quantity) as max_quantity from inventory i left outer join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id where ss.store_id in (1, 2, 4, 6) group by ss.product_id, date_trunc('MONTH', ss.sale_date) having max(i.quantity) - min(i.quantity) >= 29 order by quantity_range desc, product_id, sale_month limit 1
